You assess retrieved reference tests for unit-test generation.
A generator must write a Hardhat (ethers 6, Mocha/Chai) unit-test suite for the TARGET Solidity contract below.
It receives example tests retrieved from a corpus of OTHER contracts. Such examples are never written for the target:
a different contract name is expected and is NOT a reason for a low rating. Judge only their value as a template.

Rate the RETRIEVED TEST:
2 = directly adaptable: it exercises a behaviour that the target also implements (same kind of operation, state change,
    access rule or revert condition); its setup, calls, assertions or revert checks could be reused after renaming.
1 = partially useful: it shows a generic testing pattern applicable to the target (e.g., access-control revert, event
    assertion, time manipulation, balance change, deployment with constructor arguments), but the specific behaviour it
    tests does not exist in the target.
0 = not useful: neither its behaviour nor its testing pattern applies to the target.

Give a reason of at most 30 words, then the rating.

TARGET CONTRACT:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract SimpleStorage {
    uint256 private storedData;

    function set(uint256 value) external {
        storedData = value;
    }

    function get() external view returns (uint256) {
        return storedData;
    }
}

RETRIEVED TEST:
// corpus-v2 pair sbtchain--sergio11 (nft-marketplace, moderate)
// SBTChain.test.js: SBTChain Contract > Minting SBTs > should mint an SBT to an approved recipient
const { expect } = require("chai");
const { ethers } = require("hardhat");
let SBTChain, sbtChain, owner, approvedRecipient, revoker, anotherAccount;
let tokenId;
// beforeEach of suite "SBTChain Contract"
beforeEach(async function () {
    // Get accounts from Hardhat
    [owner, approvedRecipient, revoker, anotherAccount] = await ethers.getSigners();

    // Deploy the contract
    SBTChain = await ethers.getContractFactory("SBTChain");
    sbtChain = await SBTChain.deploy(owner.address);  // Initialize contract with the owner address
    // Set revoker address
    await sbtChain.setRevoker(revoker.address);
  })
// beforeEach of suite "Minting SBTs"
beforeEach(async function () {
      // Approve the recipient before minting
      await sbtChain.approveRecipient(approvedRecipient.address);
    })
it("should mint an SBT to an approved recipient", async function () {
      const uri = "https://example.com/metadata";
      const actionType = 1;  // Assuming ActionType is an enum where 1 represents a donation
      const description = "Donated to charity";
      const proofHash = ethers.keccak256(ethers.toUtf8Bytes(description));

      // Mint the SBT
      await sbtChain.connect(owner).mintSBT(approvedRecipient.address, uri, actionType, description, proofHash);

      tokenId = 1;  // First token ID minted
      const tokenOwner = await sbtChain.ownerOf(tokenId);
      const tokenURI = await sbtChain.tokenURI(tokenId);
      const sbtData = await sbtChain.getSBTData(tokenId);

      // Check if the SBT was minted correctly
      expect(tokenOwner).to.equal(approvedRecipient.address);
      expect(tokenURI).to.equal(uri);
      expect(sbtData.actionType).to.equal(actionType);
      expect(sbtData.description).to.equal(description);
      expect(sbtData.revoked).to.be.false;
    })


